args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?mother ?motherLabel WHERE {
  VALUES ?p { dbp:mother dbo:mother dbo:parent dbp:parent }
  dbr:Anna_Maria_of_Ostfriesland ?p ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel)='en') }
}

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?mother ?motherLabel ?grandmother ?grandmotherLabel WHERE {
  VALUES ?p { dbp:mother dbo:mother }
  dbr:Anna_Maria_of_Ostfriesland ?p ?mother .

  # try common mother properties for the mother's mother
  OPTIONAL {
    VALUES ?q { dbp:mother dbo:mother dbo:parent }
    ?mother ?q ?grandmother .
    OPTIONAL { ?grandmother rdfs:label ?grandmotherLabel . FILTER(lang(?grandmotherLabel)='en') }
  }
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel)='en') }
}

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?grandmother ?grandmotherLabel WHERE {
  dbr:Anna_Maria_of_Ostfriesland (dbp:mother|dbo:mother) ?mother .
  ?mother (dbp:mother|dbo:mother) ?grandmother .
  OPTIONAL { ?grandmother rdfs:label ?grandmotherLabel . FILTER(lang(?grandmotherLabel)='en') }
}

